#include <msgpack.hpp>

#include <stack>

namespace roerei
{

class msgpack_serializer
{
public:
	msgpack_serializer();
	virtual ~msgpack_serializer();

public:
	void write_array(const std::string& name, const size_t n);
	void write_object(const std::string& name, const size_t n);
	void write_null(const std::string& name);

	void write(const std::string& key, const uint16_t x);
	void write(const std::string& key, const uint64_t x);
	void write(const std::string& key, const std::string& x);
	void write(const std::string& key, const float x);
	void write(const std::string& key, const bool x);

	virtual void dump(std::function<void(const char*, size_t)> f);
	virtual void clear();

private:
	enum type_t
	{
		array,
		map,
		non_container
	};

	struct stack_e
	{
		type_t t;
		size_t n, i;

		stack_e(type_t t, size_t n);
	};

	void add_node(const type_t t, const std::string& name, const size_t n);
	void write(const std::string& x);

	msgpack::sbuffer buffer;
	msgpack::packer<msgpack::sbuffer> pk;
	std::stack<stack_e> stack;
};

inline msgpack_serializer::msgpack_serializer()
	: buffer()
	, pk(&buffer)
	, stack()
{}

inline msgpack_serializer::~msgpack_serializer()
{}

inline msgpack_serializer::stack_e::stack_e(type_t _t, size_t _n)
	: t(_t)
	, n(_n)
	, i(0)
{}

inline void msgpack_serializer::write(const std::string& x)
{
	pk.pack_str(x.size());
	pk.pack_str_body(x.data(), x.size());
}

inline void msgpack_serializer::add_node(const type_t t, const std::string& name, const size_t n)
{
	while(!stack.empty())
	{
		stack_e& s = stack.top();

		if(s.i < s.n)
			break;

		stack.pop();
	}

	if(!stack.empty())
	{
		stack_e& s = stack.top();
		s.i++;

		if(s.t == type_t::map)
			write(name);
	}

	if(t != type_t::non_container && n > 0)
		stack.emplace(t, n);
}

inline void msgpack_serializer::write_array(const std::string& name, const size_t n)
{
	add_node(type_t::array, name, n);
	pk.pack_array(n);
}

inline void msgpack_serializer::write_object(const std::string& name, const size_t n)
{
	add_node(type_t::map, name, n);
	pk.pack_map(n);
}

inline void msgpack_serializer::write_null(const std::string& name)
{
	add_node(type_t::non_container, name, 0);
	pk.pack_nil();
}

inline void msgpack_serializer::write(const std::string& key, const uint16_t x)
{
	add_node(type_t::non_container, key, 0);
	pk.pack_uint16(x);
}

inline void msgpack_serializer::write(const std::string& key, const uint64_t x)
{
	add_node(type_t::non_container, key, 0);
	pk.pack_uint64(x);
}

inline void msgpack_serializer::write(const std::string& key, const std::string& x)
{
	add_node(type_t::non_container, key, 0);
	write(x);
}

inline void msgpack_serializer::write(const std::string& key, const float x)
{
	add_node(type_t::non_container, key, 0);
	pk.pack_float(x);
}

inline void msgpack_serializer::write(const std::string& key, const bool x)
{
	add_node(type_t::non_container, key, 0);
	if (x) {
		pk.pack_true();
	} else {
		pk.pack_false();
	}
}

